import { FC, HTMLAttributes, useEffect } from 'react';
import { useTranslation } from 'react-i18next';

import { QueryStatus } from '@reduxjs/toolkit/query';

import { Button, Modal, notification } from 'antd';
import cn from 'classnames';

import BookmarkIcon from 'assets/images/icons/bookmark.svg?react';
import DeleteIcon from 'assets/images/icons/delete.svg?react';
import EditIcon from 'assets/images/icons/edit.svg?react';
import { SourceRead, useSourcesDestroyMutation } from 'entities/Source';
import { i18n } from 'i18n';
import { useMedia } from 'shared/hooks';
import { EMainRoutes } from 'shared/typings';
import { ButtonStyleLink } from 'shared/ui';

import styles from './ActionsCell.module.scss';

interface IActionsCellProps extends HTMLAttributes<HTMLDivElement> {
	source: SourceRead;
}

export const ActionsCell: FC<IActionsCellProps> = ({ className, source, ...props }) => {
	const { t } = useTranslation();
	const isDesktop = useMedia('desktop');
	const [deleteSource, { isSuccess, status }] = useSourcesDestroyMutation();
	const [modal, contextHolder] = Modal.useModal();

	const showConfirm = () => {
		modal.confirm({
			icon: null,
			title: (
				<span className={'wordBreak'}>
					{i18n.t('Are you sure you want to remove the {{name}} site?', { name: source.name })}
				</span>
			),
			content: i18n.t('After deletion, all tethered tools will be reset and the site cannot be restored'),
			closable: true,
			maskClosable: true,
			okText: i18n.t('Delete'),
			okType: 'danger',
			onOk() {
				return deleteSource(source.uuid);
			},
		});
	};

	useEffect(() => {
		if (isSuccess && status === QueryStatus.fulfilled) {
			notification.open({
				message: t('Source deleted'),
				showProgress: true,
			});
		}
	}, [isSuccess, source.name, status, t]);

	return (
		<div {...props} className={cn(className, styles.actionsCell)}>
			{contextHolder}
			<Button color="danger" variant="text" size="large" onClick={showConfirm} icon={<DeleteIcon />} />

			{(isDesktop || !source.has_joined_offers) && (
				<ButtonStyleLink
					color="default"
					variant="text"
					size="large"
					disabled={!source.has_joined_offers}
					to={`/${EMainRoutes.MY_OFFERS}/`}
					icon={<BookmarkIcon />}
				/>
			)}
			{(isDesktop || source.has_joined_offers) && (
				<ButtonStyleLink
					color="default"
					variant="text"
					size="large"
					disabled={source.has_joined_offers}
					to={`/${EMainRoutes.SOURCES}/${EMainRoutes.EDIT}/${source.uuid}`}
					icon={<EditIcon />}
				/>
			)}
			{!isDesktop && (
				<div className={styles.bookmark_btn}>
					{source.has_joined_offers ? (
						<ButtonStyleLink
							icon={<BookmarkIcon />}
							color="default"
							variant="text"
							size="large"
							to={`/${EMainRoutes.MY_OFFERS}/`}>
							{t('Show offers')}
						</ButtonStyleLink>
					) : (
						<ButtonStyleLink
							icon={<EditIcon />}
							color="default"
							variant="text"
							size="large"
							to={`/${EMainRoutes.SOURCES}/${EMainRoutes.EDIT}/${source.uuid}`}>
							{t('Edit')}
						</ButtonStyleLink>
					)}
				</div>
			)}
		</div>
	);
};
