import { FC } from 'react';
import { useTranslation } from 'react-i18next';

import { Typography } from 'antd';

import { TLabelValue } from 'shared/typings';
import { formatQuery } from 'shared/utils';

interface IStringListCellProps {
	list: string[];
	options: TLabelValue[];
}

export const StringListCell: FC<IStringListCellProps> = ({ list, options }) => {
	const { t } = useTranslation();

	return (
		<>
			{list?.length ? (
				<Typography.Text style={{ maxWidth: 200 }} ellipsis>
					{formatQuery(list as string[], options)}
				</Typography.Text>
			) : (
				<Typography.Text type="secondary">{t('Not specified')}</Typography.Text>
			)}
		</>
	);
};
