import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import type { TableColumnsType } from 'antd';
import cn from 'classnames';

import { ActionsCell, SourceNameCell, SourceRead, StringListCell, useSourcesListQuery } from 'entities/Source';
import { getUrlParamsForApi } from 'features/Filters';
import { useMetaRetrieveQuery } from 'shared/api';
import { Table } from 'shared/ui';

import styles from './SourceList.module.scss';

interface ISourceListProps extends HTMLAttributes<HTMLDivElement> {}

export const SourceList: FC<ISourceListProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const [searchParams] = useSearchParams();
	const { data, isFetching, isLoading } = useSourcesListQuery(getUrlParamsForApi(searchParams));
	const { data: metaData, isLoading: isMetaLoading } = useMetaRetrieveQuery();

	const columns: TableColumnsType<SourceRead> = [
		{
			title: t('Source ID'),
			dataIndex: 'url',
			key: 'url',
			ellipsis: true,
			render: (_: string, record: SourceRead) => <SourceNameCell source={record} />,
		},
		{
			title: t('Vertical'),
			dataIndex: 'categories',
			key: 'categories',
			ellipsis: true,
			render: (categories: string[]) => <StringListCell list={categories} options={metaData?.categoryOptions || []} />,
		},
		{
			title: t('GEO'),
			dataIndex: 'countries',
			key: 'countries',
			ellipsis: true,
			render: (countries: string[]) => <StringListCell list={countries} options={metaData?.countryOptions || []} />,
		},
		{
			title: t('Types of traffic'),
			dataIndex: 'traffic_types',
			key: 'traffic_types',
			ellipsis: true,
			render: (traffic_types: string[]) => (
				<StringListCell list={traffic_types} options={metaData?.trafficTypeOptions || []} />
			),
		},
		{
			dataIndex: 'has_joined_offers',
			key: 'has_joined_offers',
			render: (_: string, record: SourceRead) => <ActionsCell source={record} />,
		},
	];

	return (
		<div {...props} className={cn(className, styles.sourceList)}>
			<Table
				columns={columns}
				dataCount={data?.count}
				dataSource={data?.results}
				isFirstLoading={isLoading || isMetaLoading}
				loading={isFetching}
			/>
		</div>
	);
};
