import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';

import { Button } from 'antd';
import cn from 'classnames';

import CreateIcon from 'assets/images/icons/create.svg?react';
import { EGaCategories, EGaEvents, EGaTypes, EMainRoutes } from 'shared/typings';
import { Page, PageTitle } from 'shared/ui';
import { sendGaEvent } from 'shared/utils';
import { SourceList } from 'widgets/SourceList';

import styles from './Sources.module.scss';

interface ISourcesProps extends HTMLAttributes<HTMLDivElement> {}

export const Sources: FC<ISourcesProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const navigate = useNavigate();

	const handleCreateSourceClick = () => {
		sendGaEvent(EGaEvents.CLICK_CREATE_SOURCE, {
			event_option1: EGaCategories.SOURCES,
			event_option2: EGaTypes.MY_SOURCES,
		});
		navigate(`/${EMainRoutes.SOURCES}/${EMainRoutes.CREATE}`);
	};
	return (
		<Page {...props} className={cn(className, styles.sources)}>
			<PageTitle
				component={
					<Button
						type={'primary'}
						icon={<CreateIcon />}
						onClick={handleCreateSourceClick}
						size={'large'}
						iconPosition={'end'}>
						{t('Create Source')}
					</Button>
				}>
				{t('My Sources')}
			</PageTitle>
			<SourceList />
		</Page>
	);
};

export default Sources;
