import { FC, HTMLAttributes } from 'react';

import { Typography } from 'antd';
import cn from 'classnames';

import { SourceRead } from 'entities/Source';

import styles from './SourceNameCell.module.scss';

interface ISourceNameCellProps extends HTMLAttributes<HTMLDivElement> {
	source: SourceRead;
}

export const SourceNameCell: FC<ISourceNameCellProps> = ({ className, source, ...props }) => {
	return (
		<div {...props} className={cn(className, styles.sourceNameCell)}>
			<Typography.Text>{source.uuid}</Typography.Text>
			{source?.url && (
				<Typography.Link className={styles.link} href={source.url} target={'_blank'} ellipsis title={source.url}>
					{source.url}
				</Typography.Link>
			)}
		</div>
	);
};
